	'k8dd68793' => 'Vous savez quel son vous cherchez',
	'k8de266ae' => 'Enban Records se trouve au 7 Weir Lane, à Halden Row, Easterby, et accueille chineurs et auditeurs du mercredi au dimanche, de 11:00 à 19:00.',
	'k8dea7ba5' => 'Gradé VG+ ou mieux, nettoyé',
	'k901abbca' => 'fondatrice, acheteuse : jazz et soul',
	'k905c6bd4' => 'Trois voisins réservent le bureau de 13:00 le premier jeudi de chaque mois. Ils se partagent deux casques pendant quarante-cinq minutes et n\'écoutent que les dernières rééditions dub.',
	'k90c72173' => 'Le niveau de base de la boutique',
	'k92122f06' => 'Rafael Ortega s\'occupe du nettoyage, du gradage et de la mise en place du bac du jour près de la porte à 17:00.',
	'k93370b28' => 'Notre bac d\'arrivages frais se trouve près de la porte et reçoit chaque jour d\'ouverture, à 17:00, des disques nettoyés et gradés.',
	'k946b12c4' => 'Le bureau du jeudi',
